function isoDaysAgo(n) {
  return new Date(Date.now() - n * 86400000).toISOString().slice(0, 10);
}
function isoDaysFromNow(n) {
  return new Date(Date.now() + n * 86400000).toISOString().slice(0, 10);
}

const testInvoices = [
  {
    invoiceId: 'TEST-INV-A', invoiceNumber: 'TEST-A', contactName: 'Not Yet Due Co',
    contactEmail: 'keystoneconsultancy.co@gmail.com', dueDate: isoDaysFromNow(10),
    amountDue: 100, currencyCode: 'GBP', alreadySentStage: 0,
  },
  {
    invoiceId: 'TEST-INV-B', invoiceNumber: 'TEST-B', contactName: 'Eight Days Overdue Co',
    contactEmail: 'keystoneconsultancy.co@gmail.com', dueDate: isoDaysAgo(8),
    amountDue: 200, currencyCode: 'GBP', alreadySentStage: 0,
  },
  {
    invoiceId: 'TEST-INV-C', invoiceNumber: 'TEST-C', contactName: 'Fifteen Days Overdue Co',
    contactEmail: 'keystoneconsultancy.co@gmail.com', dueDate: isoDaysAgo(15),
    amountDue: 300, currencyCode: 'GBP', alreadySentStage: 1,
  },
  {
    invoiceId: 'TEST-INV-D', invoiceNumber: 'TEST-D', contactName: 'Twenty-Five Days Overdue Co',
    contactEmail: 'keystoneconsultancy.co@gmail.com', dueDate: isoDaysAgo(25),
    amountDue: 400, currencyCode: 'GBP', alreadySentStage: 2,
  },
  {
    invoiceId: 'TEST-INV-E', invoiceNumber: 'TEST-E', contactName: 'Already Reminded Co (dedup check)',
    contactEmail: 'keystoneconsultancy.co@gmail.com', dueDate: isoDaysAgo(8),
    amountDue: 150, currencyCode: 'GBP', alreadySentStage: 1,
  },
];

return [{ json: { testMode: true, testInvoices } }];

const config = $input.item.json;
const trigger = $('Collections Check In').item.json;
return [{ json: { ...config, testMode: trigger.testMode, testInvoices: trigger.testInvoices || [] } }];

const items = $input.all();
const first = items[0].json;
const list = Array.isArray(first) ? first : [first];
const tenantId = list[0] ? list[0].tenantId : null;
const prior = $('Merge Config + Trigger Input').item.json;
return [{ json: { ...prior, xeroTenantId: tenantId } }];

const resp = $input.item.json;
const prior = $('Build Real Invoices List').item.json;
const contact = (resp.Contacts || [])[0] || {};
return [{ json: { ...prior, contactEmail: contact.EmailAddress || prior.contactEmail || '' } }];

const resp = $input.item.json;
const prior = $('Merge Contact Email').item.json;
const records = resp.HistoryRecords || [];
let alreadySentStage = 0;
for (const rec of records) {
  const m = String(rec.Details || '').match(/COLLECTIONS_STAGE=(\d)/);
  if (m) alreadySentStage = Math.max(alreadySentStage, Number(m[1]));
}
return [{ json: { ...prior, alreadySentStage } }];

const d = $input.item.json;
const dueDateStr = String(d.dueDate || '').slice(0, 10);
const [dy, dm, dd] = dueDateStr.split('-').map(Number);
const dueUTC = Date.UTC(dy || 1970, (dm || 1) - 1, dd || 1);
const now = new Date();
const todayUTC = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate());
const daysOverdue = Math.floor((todayUTC - dueUTC) / 86400000);

const r1 = Number(d.collectionsReminder1Days) || 7;
const r2 = Number(d.collectionsReminder2Days) || 14;
const r3 = Number(d.collectionsReminder3Days) || 21;

let targetStage = 0;
if (daysOverdue >= r3) targetStage = 3;
else if (daysOverdue >= r2) targetStage = 2;
else if (daysOverdue >= r1) targetStage = 1;

const alreadySentStage = Number(d.alreadySentStage) || 0;
const shouldSend = targetStage > 0 && targetStage > alreadySentStage;

return [{ json: { ...d, daysOverdue, targetStage, shouldSend } }];

const d = $input.item.json;
const reason = d.targetStage === 0 ? 'not_yet_due' : 'already_sent_this_stage';
return [{ json: { ...d, actionTaken: 'no_action', noActionReason: reason, emailSent: false, historyWritten: false, historyWriteSkipped: false } }];

